create or replace function public.fail_semantic_group(caller_id uuid,target_job uuid,claim_token uuid,failure text) returns void language plpgsql security invoker set search_path='' as $$ begin if failure !~ '^(provider|timeout|persistence|invalid_output(:[a-z_]+)?)$' then raise exception 'INVALID_FAILURE';end if; update private.semantic_group_jobs set status=case when status='validated' then 'validated' else 'failed' end,error_code=failure,available_at=now()+interval '2 minutes' where user_id=caller_id and id=target_job and token=claim_token and status in ('processing','validated');end $$;
